import{_ as t,o as n,c as a,a0 as o}from"./chunks/framework.CLbANrvH.js";const p=JSON.parse('{"title":"What is neuron?","description":"Apache-2.0 Rust inference runtime for LLM / TTS / ASR / Rerank / Embedding / Vision","frontmatter":{"title":"What is neuron?","description":"Apache-2.0 Rust inference runtime for LLM / TTS / ASR / Rerank / Embedding / Vision","layout":"home","hero":{"name":"neuron","text":"Neural Inference Runtime","tagline":"OpenAI- and Anthropic-compatible. Library-only. Embed into any Rust host.","actions":[{"theme":"brand","text":"Quick Start","link":"/guide/quick-start"},{"theme":"alt","text":"GitHub","link":"https://github.com/ibloc/neuron"},{"theme":"alt","text":"API Reference","link":"/reference/api"}]},"features":[{"title":"🤖 9 Capability Surfaces","details":"LLM (Qwen / Llama / Phi / Mistral / ChatGLM / Gemma / MiniCPM5 / 40+ via mistralrs) ·\\nTTS (VoxCPM 0.5B + VoxCPM2 2B/48kHz) · ASR (Whisper + SenseVoice) ·\\nRerank (BGE / mxbai / jina / Cohere) · Embedding (MiniLM BERT) ·\\nVision (YOLOv8 / RT-DETR / DETR / RF-DETR / Florence-2) ·\\nOCR (PP-OCRv5/v6 + layout + tables) · Decision (Laya) ·\\nForecasting (Chronos2)\\n"},{"title":"🔌 OpenAI + Anthropic Wire-Format","details":"10+ OpenAI-compatible routes (/v1/chat/completions, /v1/audio/speech,\\n/v1/embeddings, /v1/rerank, /v1/vision/*, /v1/ocr/recognize,\\n/v1/models/pull, …) + /v1/messages for Anthropic Messages v1 (vision,\\ntool_use, cache_control, extended thinking, streaming SSE).\\n"},{"title":"🛠 3 ML Frameworks, Pick What Fits","details":"candle (default, LLM/ASR/Rerank/Embedding/Vision) · burn (TTS via VoxCPM) ·\\nlitert_lm (on-device LLM via subprocess) — plus tract / ort ONNX\\nexecutors (SenseVoice ASR, Laya decisions, PP-OCR pipeline). Feature\\nflags let you opt in to just the engines you need.\\n"},{"title":"🧠 Bounded-Memory Model Scheduler","details":"More models than fit in RAM: requests queue while resident work\\ndrains, weights swap LRU-first, idle models recycle. RSS-observed\\nmemory profiles self-correct at runtime. Off-switch included.\\n"},{"title":"📦 Library-Only, Embedded","details":"No standalone daemon. Hosts call neuron::run_embedded(...) and get back a\\nNeuronHandle that owns the axum server lifetime. Drop neuron into Tauri 2 /\\nFlutter (via cargo-ndk) / server-side process / any Rust binary.\\n"},{"title":"🌍 Multi-Source Model Registry","details":"Plug-in sources for HuggingFace, hf-mirror (China CDN), ModelScope.\\nPer-engine and per-model source overrides. <source>:<repo> syntax in\\nPOST /v1/models/pull with default-source fallback. Catalog dedup\\nacross sources.\\n"},{"title":"📜 Apache-2.0","details":"Released under the Apache License 2.0. In-house VoxCpm vendored under\\nsrc/tts/voxcpm_burn/ and clean-room YOLOv8 architecture in\\nsrc/vision/yolov8_arch.rs. No AGPL-3.0, no copyleft.\\n"}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1791849617000}'),r={name:"index.md"};function i(s,e,d,l,c,h){return n(),a("div",null,[...e[0]||(e[0]=[o('<h2 id="what-is-neuron" tabindex="-1">What is neuron? <a class="header-anchor" href="#what-is-neuron" aria-label="Permalink to &quot;What is neuron?&quot;">​</a></h2><p><code>neuron</code> is a <strong>library-only</strong> Rust crate that hosts an OpenAI-compatible (and Anthropic Messages v1) HTTP inference server inside any Rust embedder process. It&#39;s designed for AI user-avatars / agent systems / Tauri desktop shells / Flutter mobile apps that need a full inference stack (LLM + TTS + ASR + Rerank + Embedding + Vision) without standing up a separate daemon.</p><p>The wire format is byte-for-byte OpenAI / vLLM / ollama / llama.cpp / Anthropic SDK compatible, so any client that already works with those services will work with neuron unchanged.</p><h2 id="at-a-glance" tabindex="-1">At a glance <a class="header-anchor" href="#at-a-glance" aria-label="Permalink to &quot;At a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Surface</th><th>Endpoints</th></tr></thead><tbody><tr><td><strong>OpenAI-compatible</strong></td><td><code>POST /v1/chat/completions</code>, <code>POST /v1/audio/speech</code>, <code>POST /v1/audio/transcriptions</code>, <code>POST /v1/embeddings</code>, <code>POST /v1/rerank</code>, <code>POST /v1/vision/{detect,classify,segment,pose}</code>, <code>POST /v1/vision/lora/{register,unregister}</code>, <code>GET /v1/vision/lora/list</code>, <code>GET /v1/models</code>, <code>POST /v1/models/pull</code>, <code>GET /v1/catalog/sources</code></td></tr><tr><td><strong>Anthropic Messages v1</strong></td><td><code>POST /v1/messages</code> (vision, tool_use, cache_control, extended thinking, streaming SSE)</td></tr><tr><td><strong>Liveness</strong></td><td><code>GET /health</code>, <code>GET /v1/info</code></td></tr></tbody></table><h2 id="why-a-library-not-a-binary" tabindex="-1">Why a library, not a binary? <a class="header-anchor" href="#why-a-library-not-a-binary" aria-label="Permalink to &quot;Why a library, not a binary?&quot;">​</a></h2><p>Most inference servers (vLLM, ollama, llama.cpp server) are standalone daemons — they bind a port, you point clients at it. That&#39;s the right model for shared GPU servers. It&#39;s the wrong model for embedding into a desktop app or mobile binary:</p><ul><li><strong>Tauri 2 desktop shell</strong>: each Tauri app should ship neuron as part of its binary, not spawn a sidecar.</li><li><strong>Flutter mobile (via cargo-ndk)</strong>: neuron becomes a shared library loaded by a Kotlin/Swift shim.</li><li><strong>Server-side process</strong>: any HTTP gateway or orchestrator agent that already has its own main loop.</li></ul><p><code>neuron::run_embedded(NeuronEmbedConfig { port: 8085, ... })</code> returns a <code>NeuronHandle</code> that owns the axum server&#39;s lifetime. The host calls <code>handle.request_shutdown()</code> + <code>handle.join().await</code> for graceful drain. Drop the handle without shutdown and you leak the bind port — so the type system enforces correct lifecycle.</p><h2 id="where-to-next" tabindex="-1">Where to next? <a class="header-anchor" href="#where-to-next" aria-label="Permalink to &quot;Where to next?&quot;">​</a></h2><ul><li><a href="/neuron/guide/quick-start">Quick Start</a> — embed neuron in a Rust binary in 20 lines</li><li><a href="/neuron/concepts/architecture">Architecture</a> — how the data flow works end-to-end</li><li><a href="/neuron/concepts/capabilities">Capabilities</a> — the 9 model surfaces, in detail</li><li><a href="/neuron/reference/api">OpenAI-compatible API</a> — full route table</li></ul>',11)])])}const m=t(r,[["render",i]]);export{p as __pageData,m as default};
